import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.DXa1R37q.js";const u=JSON.parse('{"title":"Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/requirements.md","filePath":"get-started/requirements.md","lastUpdated":1792947882000}'),a={name:"get-started/requirements.md"};function d(n,e,i,c,l,m){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h1><p>Check these restrictions before a filesystem quick start. Filesystem-backed Memory, Issues, and Design Docs fail closed outside the supported environment.</p><table tabindex="0"><thead><tr><th>Component</th><th>Runtime</th><th>Other requirements</th></tr></thead><tbody><tr><td><code>@neottia/core</code></td><td>Node.js 20 or newer</td><td>Browser bundles are also published.</td></tr><tr><td>Repository Store and filesystem domains</td><td>Node.js 22.16 or newer, or Bun 1.3.13 or newer for direct Repository Store use</td><td>Linux x64 or arm64; C++17 compiler, Python, Make, and Linux headers for native builds.</td></tr><tr><td>MCP servers</td><td>Node.js 22.16 or newer</td><td>The same filesystem requirements as their domain.</td></tr><tr><td>Pi and OpenCode extensions</td><td>Host Node.js runtime</td><td>The same requirements as their domain package.</td></tr><tr><td>PostgreSQL Memory</td><td>Node.js 22.16 or newer</td><td>PostgreSQL credentials and an explicit organization, project, and scope ownership model.</td></tr><tr><td>Searchable</td><td>Node.js 22.16 or newer</td><td>Repository Store filesystem support; public network access; Ollama only when using <code>web_ask</code>.</td></tr></tbody></table><p>Filesystem domains require a recognized local ext4, XFS, Btrfs, tmpfs, or overlay filesystem. The kernel must provide <code>renameat2(RENAME_NOREPLACE)</code>, and the canonical root and control directory must support same-volume hard links. macOS, Windows, network or shared filesystems, unsupported kernels or C libraries, and missing native builds fail closed for leased operations.</p><p>All four capability shards default to <code>enabled: false</code>. Enable only the capabilities you use.</p><p>Pi can ask before rebuilding a stale cache. OpenCode and MCP are non-interactive, so <code>prompt</code> becomes <code>rebuild</code>. An explicit <code>fail</code> remains <code>fail</code>.</p><p>If a native addon fails to install, confirm the Node version, architecture, compiler, Python, Make, headers, filesystem, and kernel support. Do not treat <code>UnsupportedRuntimeError</code> as canonical-data corruption. See <a href="/projects/neottia/repository-store">Repository Store diagnostics</a>.</p>',7)])])}const h=t(a,[["render",d]]);export{u as __pageData,h as default};
